// lunar-station — космос, эмбиент 2 in E лидийский (0 2 4 6 7 9 11), 68 BPM. Generated by MathMusic
// (style space2, seed 1): launch → nebula → orbit → drift → dark side → eclipse → silence.
// Themes: A — Distant Signal (далёкий сигнал) (recomposed), B — Weightless (невесомость) (as written); the bridge melody is newly
// composed on the rhythm of a theme from classical. Computed parts: a counter-melody from the chords, the theme at half speed in the outro, a key change up.
// It is an ordinary song file: change anything; the melodies can be drawn in the piano roll (P).
// x is time in beats; n counts semitones from C4 (MIDI 60).
import { TAU, delay, exp, filter, floor, hz, mod, noise, osc, reverb, sin, smooth, tanh } from '../src/engine.js'
import {
  arrangement, cymbal2, ensemble, hall, hash, improvise, kick2, notesAt, pan, poly, polyWide, rimDrum, section, softPluckTone, soloist, trigger,
} from '../src/instruments.js'

const SECTIONS = [[0,"launch"],[16,"nebula"],[48,"orbit"],[80,"drift"],[96,"dark side"],[128,"eclipse"],[160,"silence"]]
const END = 184
const part = arrangement(SECTIONS)
const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",0],[16,"themeB",1],[48,"theme",2],[80,"break",0],[96,"bridge",1],[128,"final",3],[160,"outro",0]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

// ---- harmony: [start beat, length, bass MIDI, voicing MIDI (voice-led), chord, [3rd, 5th, 7th]] --
const HARMONY = [
  [0, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [4, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [8, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [12, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [16, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [20, 4, 35, [54, 59, 63], 'B', [4, 7, 10]],
  [24, 4, 34, [58, 61, 64], 'A♯°', [3, 6, 10]],
  [28, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [32, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [36, 4, 34, [58, 61, 64], 'A♯°', [3, 6, 10]],
  [40, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [44, 4, 35, [54, 59, 63], 'B', [4, 7, 10]],
  [48, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [52, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [56, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [60, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [64, 4, 32, [56, 59, 63], 'G♯m', [3, 7, 10]],
  [68, 4, 32, [56, 59, 63], 'G♯m', [3, 7, 10]],
  [72, 4, 37, [54, 58, 61], 'C♯sus4', [5, 7, 9]],
  [76, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [80, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [84, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [88, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [92, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [96, 4, 40, [56, 59, 63, 64], 'Emaj7', [4, 7, 11]],
  [100, 4, 37, [56, 59, 61, 64], 'C♯m7', [3, 7, 10]],
  [104, 4, 30, [54, 58, 61, 64], 'F♯7', [4, 7, 10]],
  [108, 4, 35, [54, 58, 59, 63], 'Bmaj7', [4, 7, 11]],
  [112, 4, 40, [52, 56, 59, 63], 'Emaj7', [4, 7, 11]],
  [116, 4, 37, [52, 56, 59, 61], 'C♯m7', [3, 7, 10]],
  [120, 4, 30, [52, 54, 58, 61], 'F♯7', [4, 7, 10]],
  [124, 4, 35, [51, 54, 58, 59], 'Bmaj7', [4, 7, 11]],
  [128, 4, 30, [49, 54, 58], 'F♯', [4, 7, 10]],
  [132, 4, 30, [49, 54, 58], 'F♯', [4, 7, 10]],
  [136, 4, 39, [51, 54, 58], 'D♯m', [3, 7, 10]],
  [140, 4, 39, [51, 54, 58], 'D♯m', [3, 7, 10]],
  [144, 4, 34, [49, 53, 58], 'A♯m', [3, 7, 10]],
  [148, 4, 34, [49, 53, 58], 'A♯m', [3, 7, 10]],
  [152, 4, 39, [51, 56, 60], 'D♯sus4', [5, 7, 9]],
  [156, 4, 30, [54, 58, 61], 'F♯', [4, 7, 10]],
  [160, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [164, 4, 40, [56, 59, 64], 'E', [4, 7, 10]],
  [168, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [172, 4, 37, [56, 61, 64], 'C♯m', [3, 7, 10]],
  [176, 4, 32, [56, 59, 63], 'G♯m', [3, 7, 10]],
  [180, 4, 32, [56, 59, 63], 'G♯m', [3, 7, 10]],
]
const BY_BEAT = []
for (const h of HARMONY) for (let b = h[0]; b < h[0] + h[1]; b++) BY_BEAT[b] = h
const chordAt = x => BY_BEAT[floor(x)] ?? null
const padOn = x => chordAt(x) && ['themeB', 'bridge', 'break', 'final', 'intro'].includes(role(x)) && x < END - 2 // pads play here
const SCALE = [4, 6, 8, 10, 11, 1, 3] // E — лидийский, pitch classes from C

// ---- the stage: sections, key changes -----------------------------------------------------------
const SEC = 60 / 68 // seconds per beat
const sectionEnd = x => ROLE.find(r => r[0] > x)?.[0] ?? END
const KEY_UP = [[128,2]] // [start, semitones up]
const trAt = x => { let t = 0; for (const [s, k] of KEY_UP) if (s <= x) t = k; return t }
const pumpAt = () => 1

// ---- melodies: [beat, n from C4, length] — draw them in the piano roll ------------------------------
// A — Distant Signal (далёкий сигнал), recomposed; in E — лидийский
const THEME_A = [
  [0, 8, 2], [2, 8, 2],
  [4, 11, 3], [7, 13, 1],
  [8, 16, 2], [10, 16, 2],
  [12, 20, 4],
  [16, 20, 2], [18, 20, 2],
  [20, 15, 3], [23, 16, 1],
  [24, 18, 2], [26, 18, 2],
  [28, 16, 4],
]
// B — Weightless (невесомость), as written
const THEME_B = [
  [0, 8, 3], [3, 11, 1],
  [4, 15, 2], [6, 11, 2],
  [8, 13, 3], [11, 11, 1],
  [12, 8, 4],
  [16, 13, 2], [18, 16, 2],
  [20, 16, 3], [23, 13, 1],
  [24, 11, 2], [26, 20, 2],
  [28, 18, 4],
]
// the bridge — composed over Emaj7 – C♯m7 – F♯m7 – B7
const BRIDGE = [
  [0, 8, 2], [2, 11, 2],
  [4, 13, 2], [6, 16, 2],
  [8, 18, 2], [10, 16, 2],
  [12, 18, 2], [14, 18, 2],
]
const REST = []
const SOLO = []
const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[48,"A",0,1],[80,"A",0,1],[96,"REST",0,1],[128,"A",2,1],[160,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[48,"REST",0,1],[80,"REST",0,1],[96,"BRIDGE",0,1],[112,"BRIDGE",0,1],[128,"REST",0,1],[160,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[48,"REST",0,1],[80,"REST",0,1],[96,"REST",0,1],[128,"HARMONY",0,1],[160,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- softlead ----------------------------------------------------------------------------------
const track0 = {
  color: '#a0e7e5',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["y = \\Rev\\Big[a(\\tau)\\sum_{k} A_k\\sin\\big(2\\pi k\\!\\int\\! f\\,dt + \\varphi_k\\big)\\Big],\\quad A_k = \\frac{B(kf)}{k^{p}}\\ \\text{— гармоники по спектру инструмента: наклон источника и резонансы корпуса}","f = f_0\\,2^{(v(\\tau)\\sin 2\\pi f_v t - s\\,e^{-\\tau/45\\text{мс}})/1200}\\ \\text{— вибрато приходит позже, подъезд к ноте, легато — глиссандо}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = soloist('sine', { vib: 1, glide: 0.06, scoop: 0, accent: 0, seed: 5 }), verb = hall({ size: 1.25, decay: 3.6, damp: 4600, wet: 0.34 }), echo = delay({ time: sec * 0.75, feedback: 0.3, wet: 0.26 })
    let n = 0, vel = 0.8
    return x => {
      const m = leadAt(x)
      if (m) { n = m.n; vel = 0.6 + 0.07 * Math.max(0, energy(x)) + 0.16 * hash(floor(2 * m.at), 5) + (mod(m.at, 4) === 0 ? 0.06 : 0) }
      const on = !!m && m.u < 0.94, f = hz(n + 0, C4)
      const y = 3.6 * (a(f, on, vel))
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

// ---- softpluck ---------------------------------------------------------------------------------
const track1 = {
  color: '#7ff5d0',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["P = \\Rev\\sum_{k}\\big(0.72\\,e^{-t/\\tau_k} + 0.28\\,e^{-t/5\\tau_k}\\big)A_k(v)\\sin 2\\pi f_k t,\\quad f_k = kf\\sqrt{1 + Bk^2}\\ \\text{— струна с жёсткостью, быстрый звук и послезвучие}","A_k(v) = \\frac{|\\sin(0.123\\pi k)|^{0.6}}{k^{\\,0.75 + 1.1(1 - v)}}\\cdot\\frac{1}{1 + (f_k/f_c(v))^2}\\ \\text{— удар на ⅛ струны, войлок твёрже при сильном ударе}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = polyWide(softPluckTone, { release: 0.25, life: 3, width: 0.5 }), fire = trigger(), verb = hall({ size: 1.25, decay: 3.6, damp: 4600, wet: 0.34 }), echo = delay({ time: sec * 0.75, feedback: 0.32, wet: 0.3 })
    return x => {
      const m = lead2At(x)
      if (fire(m ? m.at : null)) {
        const v = 0.62 + 0.08 * Math.max(0, energy(x)) + 0.14 * hash(floor(4 * m.at), 3) + (mod(m.at, 4) === 0 ? 0.06 : 0)
        p.hit(hz(m.n + 0, C4), v, m.d * sec + 0.25)
      }
      const [l, r] = p(), k = 0.9945
      return verb(...echo(k * l, k * r).map((s, i) => s * (i ? 0.7 : 1.3)))
    }
  },
}

// ---- softlead counter --------------------------------------------------------------------------
const track2 = {
  color: '#a0e7e5',
  graph: x => { const m = counterAt(x); return m ? 0.8 + (m.n + 5) * 0.0471 : null },
  midi: x => { const m = counterAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["y = \\Rev\\Big[a(\\tau)\\sum_{k} A_k\\sin\\big(2\\pi k\\!\\int\\! f\\,dt + \\varphi_k\\big)\\Big],\\quad A_k = \\frac{B(kf)}{k^{p}}\\ \\text{— гармоники по спектру инструмента: наклон источника и резонансы корпуса}","f = f_0\\,2^{(v(\\tau)\\sin 2\\pi f_v t - s\\,e^{-\\tau/45\\text{мс}})/1200}\\ \\text{— вибрато приходит позже, подъезд к ноте, легато — глиссандо}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = soloist('sine', { vib: 1, glide: 0.06, scoop: 0, accent: 0, seed: 5 }), verb = hall({ size: 1.25, decay: 3.6, damp: 4600, wet: 0.34 }), echo = delay({ time: sec * 0.75, feedback: 0.3, wet: 0.26 })
    let n = 0, vel = 0.8
    return x => {
      const m = counterAt(x)
      if (m) { n = m.n; vel = 0.6 + 0.07 * Math.max(0, energy(x)) + 0.16 * hash(floor(2 * m.at), 5) + (mod(m.at, 4) === 0 ? 0.06 : 0) }
      const on = !!m && m.u < 0.94, f = hz(n + 0, C4)
      const y = 1.44 * (a(f, on, vel))
      return verb(...echo(...pan(y, -0.4)))
    }
  },
}

// ---- glassswell --------------------------------------------------------------------------------
const track3 = (() => {
  const RHYTHM = null
  // is the section playing at x, and how hard (0 = no)
  const strokeAt = x => {
    const c = chordAt(x), e = energy(x)
    if (!c || e < 1 || x >= END - 0.5) return 0
    if (!RHYTHM) return 1
    const pat = RHYTHM[e] ?? RHYTHM[2], i = floor(4 * mod(x, 4) + 1e-6), ch = pat ? pat[i] : '-'
    return (ch === 'x' ? 1 : ch === 'o' ? 0.6 : 0) * (mod(4 * x, 1) < 0.8 ? 1 : 0)
  }
  return {
  color: '#bde0fe',
  graph: x => (strokeAt(x) ? chordAt(x)[3].map(n => -1 + (n - 48) / 20) : null),
  midi: x => (strokeAt(x) ? chordAt(x)[3] : []),
  formula: ["Pd = \\Rev\\sum_{j}\\sum_{i=1}^{N} a_i\\,W_{d}\\big(f_j\\,2^{(\\delta_i + v_i(t))/1200}\\big),\\quad W_d = \\sum_k \\frac{B(kf)}{k^{p(d)}}\\sin(2\\pi kft + \\varphi_k)\\ \\text{— N исполнителей на каждой ноте, каждый на несколько центов в стороне, со своим вибрато и местом в зале}"],
  audio() {
    const S = [section('glass', { players: 4, centre: 0, spread: 0.8, vib: 1, attack: 0.6, release: 1.2, seed: 40 }), section('sine', { players: 2, centre: 0, spread: 0.8, vib: 1, attack: 0.8, release: 1.2, seed: 41 })], NONE = [], verb = hall({ size: 1.5, decay: 9, damp: 3000, pre: 0.04, mod: 1.6, wet: 0.5 })
    let F = S.map(() => NONE), last = null
    return x => {
      const st = strokeAt(x), on = st > 0, c = on ? chordAt(x) : null
      if (c && c !== last) { last = c; F = [c[3].map(n => hz(n + 0 - 60, C4)), c[3].map(n => hz(n + 12 - 60, C4))] }
      const lv = ([0.3,0.45,0.62,0.85][Math.max(0, energy(x))] ?? 0.4) * (0.6 + 0.4 * st)
      let l = 0, r = 0
      { const [a, b] = S[0](on ? F[0] : NONE, lv); l += 1 * a; r += 1 * b }
      { const [a, b] = S[1](on ? F[1] : NONE, lv); l += 0.3 * a; r += 0.3 * b }
      const k = 0.65 * (0.7 + 0.5 * lv)
      return verb(k * l, k * r)
    }
  },
}})()

// ---- starpad -----------------------------------------------------------------------------------
const track4 = {
  color: '#caf0f8',
  graph: x => ((!!chordAt(x) && x < END - 1) ? chordAt(x)[3].map(n => -1.7 + (n - 48) / 30) : null),
  midi: x => ((!!chordAt(x) && x < END - 1) && mod(x, 4) < 3.9 ? chordAt(x)[3] : []),
  formula: ["Pd = \\Rev\\sum_{j}\\sum_{i=1}^{N} a_i\\,W_{d}\\big(f_j\\,2^{(\\delta_i + v_i(t))/1200}\\big),\\quad W_d = \\sum_k \\frac{B(kf)}{k^{p(d)}}\\sin(2\\pi kft + \\varphi_k)\\ \\text{— N исполнителей на каждой ноте, каждый на несколько центов в стороне, со своим вибрато и местом в зале}"],
  audio() {
    const S = [section('glass', { players: 4, centre: 0, spread: 0.8, vib: 1, seed: 20 }), section('warm', { players: 4, centre: 0, spread: 0.8, vib: 1, seed: 21 })], NONE = [], verb = hall({ size: 1.5, decay: 9, damp: 3000, pre: 0.04, mod: 1.6, wet: 0.45 }), ens = ensemble({ mix: 0.4 })
    let F = S.map(() => NONE), last = null
    return x => {
      const on = (!!chordAt(x) && x < END - 1), c = on ? chordAt(x) : null
      if (c && c !== last) { last = c; F = [c[3].map(n => hz(n + 0 - 60, C4)), c[3].map(n => hz(n + -12 - 60, C4))] }
      const lv = [0.3,0.45,0.62,0.85][Math.max(0, energy(x))] ?? 0.4
      let l = 0, r = 0
      { const [a, b] = S[0](on ? F[0] : NONE, lv); l += 0.9 * a; r += 0.9 * b }
      { const [a, b] = S[1](on ? F[1] : NONE, lv); l += 0.55 * a; r += 0.55 * b }
      const k = 0.6 * (0.7 + 0.5 * lv)
      return verb(...ens(k * l, k * r))
    }
  },
}

// ---- bass --------------------------------------------------------------------------------------
const track5 = (() => {
  const BASS_LINE = [[0,"R",3.8]]
const bassAt = x => {
  const c = chordAt(x), e = energy(x)
  if (!c || e < 1 || x >= END - 1) return null
  const p = mod(x, 4), bar = floor(x / 4) * 4
  let hit = null
  for (const h of BASS_LINE) if (h[0] <= p && p < h[0] + h[2]) hit = h
  if (!hit) return null
  const next = chordAt(bar + 4) ?? c, [third, fifth] = c[5]
  const n = hit[1] === 'R' ? c[2] : hit[1] === '5' ? c[2] + fifth : hit[1] === '8' ? c[2] + 12 : hit[1] === '3' ? c[2] + third : next[2] - 1
  return { n, at: bar + hit[0], d: hit[2] }
}
  return {
  color: '#4d7cff',
  graph: x => (bassAt(x) ? -3 + (bassAt(x).n - 28) / 24 : null),
  midi: x => (bassAt(x) && x - bassAt(x).at < bassAt(x).d * 0.9 ? [bassAt(x).n] : []),
  formula: ["Sb = \\tanh\\!\\big(1.6\\,a\\,(\\sin\\varphi + 0.12\\sin 2\\varphi)\\big),\\quad \\varphi = 2\\pi\\!\\int\\! f,\\ f \\text{ — скользит к новой ноте 25 мс}"],
  audio({ bpm }) {
    const o1 = osc('sine'), o2 = osc('sine'), glide = smooth(25), env = smooth(9)
    let n = 36
    return x => {
      const m = bassAt(x), on = m && x - m.at < m.d * 0.9
      if (m) n = m.n
      const f = hz(glide(n) - 60, C4), a = env(on ? 1 : 0)
      return 0.3906 * tanh(1.6 * a * (o1(f) + 0.12 * o2(2 * f))) / 0.9217
    }
  },
}})()

// ---- starseq arp -------------------------------------------------------------------------------
const track6 = (() => {
  const PATTERN = [0,2,1,3,2,1,3,2]
  const arpAt = x => {
    const e = energy(x)
    if (e < 1 || x >= END - 1 || !["theme","themeB","bridge","final"].includes(role(x))) return null
    const j = floor(x * 2 + 1e-9), c = chordAt(j / 2)
    if (!c) return null
    const v = c[3], i = PATTERN[mod(j, PATTERN.length)]
    return { n: v[i % v.length] + 12 * floor(i / v.length) + 12, at: j / 2, vel: mod(j, 8) === 0 ? 0.8 : 0.55, j }
  }
  return {
  color: '#7ff5d0',
  graph: x => (arpAt(x) && x - arpAt(x).at < 0.2 ? 0.3 + (arpAt(x).n - 55) / 40 : null),
  midi: x => (arpAt(x) && x - arpAt(x).at < 0.24 ? [arpAt(x).n] : []),
  formula: ["\\text{арпеджио: } n_j = v_{p_{j \\bmod 8}},\\quad p = (0,2,1,3,2,1,3,2)\\ \\text{— ноты аккорда снизу вверх, каждая на своей стороне}"],
  audio({ bpm }) {
    const sec = 60 / bpm, L = poly(softPluckTone, { release: 0.4, life: 3, max: 14 }), R = poly(softPluckTone, { release: 0.4, life: 3, max: 14 }), fire = trigger(), verb = hall({ size: 1.5, decay: 9, damp: 3000, pre: 0.04, mod: 1.6, wet: 0.42 }), echo = delay({ time: sec * 0.75, feedback: 0.36, wet: 0.4 })
    return x => {
      const m = arpAt(x)
      if (m && fire(m.at)) (m.j % 2 ? R : L).hit(hz(m.n - 60, C4), m.vel * (0.85 + 0.15 * hash(m.j, 29)), 0.9 / 2 * sec)
      const a = L(), b = R(), k = 0.3
      return verb(...echo(k * (a + 0.5 * b), k * (b + 0.5 * a)))
    }
  },
}})()

